// Mini dataset (CONTRACT.md §4), generated by scripts/gen-fixtures.mjs. Used by InMemoryAdapter and Lane 2 mock mode.
// Parsed through the contract schemas on load, so a bad fixture fails loudly instead of drifting from the contract.
import { z } from "zod";
import { DemandItemRowSchema, KitSseEventSchema, ProductSchema, ShopSchema, VoucherSchema } from "../schemas";
import shops from "./shops.json";
import products from "./products.json";
import vouchers from "./vouchers.json";
import demandItems from "./demand-items.json";
import kitSampleJson from "./kit.sample.json";

export const fixtures = {
  shops: z.array(ShopSchema).parse(shops),
  products: z.array(ProductSchema).parse(products),
  vouchers: z.array(VoucherSchema).parse(vouchers),
  demandItems: z.array(DemandItemRowSchema).parse(demandItems),
};

/** Recorded SSE stream for the DEMO.md Beat 1 query; replayed when NEXT_PUBLIC_KITLY_MOCK=1. */
export const kitSample = z.array(KitSseEventSchema).parse(kitSampleJson);
